import React, { useEffect } from 'react';

interface SEOHeadProps {
  title: string;
  description?: string;
}

const SEOHead: React.FC<SEOHeadProps> = ({ title, description }) => {
  useEffect(() => {
    // Update Title
    document.title = `${title} | Onsective Enterprise`;

    // Update Meta Description
    const metaDescription = document.querySelector('meta[name="description"]');
    if (metaDescription) {
      metaDescription.setAttribute('content', description || "Onsective delivers premium IT strategies, cloud solutions, and cybersecurity services for global enterprises.");
    } else {
      const meta = document.createElement('meta');
      meta.name = "description";
      meta.content = description || "Onsective delivers premium IT strategies, cloud solutions, and cybersecurity services for global enterprises.";
      document.head.appendChild(meta);
    }

    // Scroll to top on route change
    window.scrollTo(0, 0);
  }, [title, description]);

  return null;
};

export default SEOHead;

import React from 'react';
import { ArrowRight } from 'lucide-react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  withArrow?: boolean;
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  withArrow = false,
  className = '',
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-medium transition-all duration-200 rounded-md focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-brand-primary text-white hover:bg-blue-700 focus:ring-brand-primary shadow-lg shadow-blue-500/30",
    secondary: "bg-brand-dark text-white hover:bg-slate-800 focus:ring-brand-dark shadow-lg shadow-slate-900/20",
    outline: "border-2 border-brand-primary text-brand-primary hover:bg-brand-primary hover:text-white focus:ring-brand-primary",
    ghost: "text-slate-600 hover:text-brand-primary hover:bg-slate-100"
  };

  const sizes = {
    sm: "px-4 py-2 text-sm",
    md: "px-6 py-3 text-base",
    lg: "px-8 py-4 text-lg font-semibold"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {children}
      {withArrow && <ArrowRight className="ml-2 w-4 h-4 md:w-5 md:h-5" />}
    </button>
  );
};

export default Button;

