import React from 'react';
import { ArrowRight } from 'lucide-react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'text';
  size?: 'sm' | 'md' | 'lg';
  withArrow?: boolean;
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  withArrow = false,
  className = '',
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-semibold transition-all duration-300 focus:outline-none disabled:opacity-50 disabled:cursor-not-allowed tracking-wide";

  const variants = {
    primary: "bg-brand-primary text-white hover:bg-brand-black border border-transparent rounded-sm",
    secondary: "bg-brand-black text-white hover:bg-brand-primary border border-transparent rounded-sm",
    outline: "border border-brand-black text-brand-black hover:bg-brand-black hover:text-white rounded-sm",
    ghost: "bg-brand-gray text-brand-black hover:bg-brand-primary hover:text-white rounded-sm",
    text: "text-brand-primary hover:text-brand-black underline-offset-4 hover:underline p-0"
  };

  const sizes = {
    sm: "px-5 py-2 text-xs uppercase",
    md: "px-7 py-3 text-sm",
    lg: "px-10 py-4 text-base"
  };

  // Text variant override
  const finalSize = variant === 'text' ? '' : sizes[size];

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${finalSize} ${className}`}
      {...props}
    >
      {children}
      {withArrow && <ArrowRight className="ml-3 w-4 h-4" />}
    </button>
  );
};

export default Button;

