import React from 'react';
import { ArrowRight } from 'lucide-react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'text';
  size?: 'sm' | 'md' | 'lg';
  withArrow?: boolean;
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  withArrow = false,
  className = '',
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-semibold transition-all duration-300 focus:outline-none disabled:opacity-50 disabled:cursor-not-allowed tracking-widest uppercase text-xs sm:text-sm";

  const variants = {
    primary: "bg-brand-primary text-brand-black hover:bg-brand-accent border border-transparent rounded-none shadow-[0_0_15px_rgba(197,160,89,0.3)]",
    secondary: "bg-brand-black text-white hover:bg-brand-secondary border border-transparent rounded-none",
    outline: "border border-brand-primary text-brand-primary hover:bg-brand-primary hover:text-brand-black rounded-none",
    ghost: "bg-transparent text-brand-dark hover:text-brand-primary rounded-none",
    text: "text-brand-primary hover:text-brand-accent underline-offset-4 hover:underline p-0 capitalize tracking-normal"
  };

  const sizes = {
    sm: "px-6 py-3",
    md: "px-8 py-4",
    lg: "px-10 py-5"
  };

  // Text variant override
  const finalSize = variant === 'text' ? '' : sizes[size];

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${finalSize} ${className}`}
      {...props}
    >
      {children}
      {withArrow && <ArrowRight className="ml-3 w-4 h-4" />}
    </button>
  );
};

export default Button;

