import React, { useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { Calendar, Clock, ChevronRight, ChevronLeft, Search as SearchIcon } from 'lucide-react';
import SEOHead from '../components/SEO/SEOHead';
import { ALL_INSIGHTS } from '../constants';
import Button from '../components/UI/Button';

const ITEMS_PER_PAGE = 9;

const CATEGORIES = [
  'All',
  'Artificial Intelligence',
  'Digital Marketing',
  'Enterprise SEO',
  'Brand Strategy',
  'Cloud Transformation',
  'Cybersecurity'
];

const Insights: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState('All');
  const [currentPage, setCurrentPage] = useState(1);
  const [searchQuery, setSearchQuery] = useState('');

  // Scroll to top when page changes
  React.useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [currentPage]);

  // Filter Logic
  const filteredPosts = useMemo(() => {
    return ALL_INSIGHTS.filter(post => {
      const matchesCategory = activeCategory === 'All' || post.category === activeCategory;
      const matchesSearch = post.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            post.excerpt.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [activeCategory, searchQuery]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredPosts.length / ITEMS_PER_PAGE);
  const currentPosts = filteredPosts.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  const handleCategoryChange = (cat: string) => {
    setActiveCategory(cat);
    setCurrentPage(1);
  };

  return (
    <>
      <SEOHead 
        title="Insights & Analysis" 
        description="Explore over 500+ expert articles on AI, Digital Marketing, SEO, and Brand Strategy."
      />

      {/* Header */}
      <section className="pt-32 pb-16 bg-brand-dark text-white px-4">
        <div className="max-w-7xl mx-auto text-center">
          <span className="text-brand-primary font-bold tracking-[0.2em] uppercase text-xs mb-4 block animate-fade-up">Knowledge Hub</span>
          <h1 className="text-4xl md:text-6xl font-serif font-bold mb-6 animate-fade-up delay-100">Insights & Resources</h1>
          <p className="text-slate-300 text-lg max-w-2xl mx-auto animate-fade-up delay-200">
            Thought leadership from our senior engineers and strategists to help you stay ahead of the technology curve.
          </p>
        </div>
      </section>

      {/* Controls Section */}
      <section className="sticky top-14 z-30 bg-white/95 backdrop-blur-md border-b border-gray-200 py-4 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                {/* Categories */}
                <div className="flex overflow-x-auto w-full md:w-auto pb-2 md:pb-0 gap-2 no-scrollbar">
                    {CATEGORIES.map(cat => (
                        <button
                            key={cat}
                            onClick={() => handleCategoryChange(cat)}
                            className={`whitespace-nowrap px-4 py-2 rounded-full text-xs font-bold uppercase tracking-widest transition-all ${
                                activeCategory === cat 
                                ? 'bg-brand-black text-white' 
                                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                            }`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>

                {/* Search */}
                <div className="relative w-full md:w-64">
                    <input 
                        type="text" 
                        placeholder="Search insights..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:border-brand-primary transition-colors text-sm"
                    />
                    <SearchIcon className="absolute left-3 top-2.5 text-gray-400" size={16} />
                </div>
            </div>
        </div>
      </section>

      <section className="py-12 bg-slate-50 min-h-screen">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

          <div className="mb-8 text-gray-500 text-sm font-medium">
            Showing {currentPosts.length} of {filteredPosts.length} articles
          </div>

          {/* Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-16">
            {currentPosts.map((post) => (
              <Link key={post.id} to={`/insights/${post.id}`} className="group flex flex-col bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 border border-gray-100">
                <div className="h-56 overflow-hidden relative">
                  <div className="absolute top-4 left-4 bg-brand-black/80 backdrop-blur-sm text-white text-[10px] font-bold uppercase tracking-widest px-3 py-1 z-10 rounded-sm">
                    {post.category}
                  </div>
                  <img src={post.image} alt={post.title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                </div>
                <div className="flex-1 p-6 flex flex-col">
                  <h3 className="text-xl font-bold text-brand-black mb-3 group-hover:text-brand-primary transition-colors line-clamp-2 font-serif">
                    {post.title}
                  </h3>
                  <p className="text-slate-600 text-sm mb-6 line-clamp-3 flex-1 font-light leading-relaxed">
                    {post.excerpt}
                  </p>
                  <div className="pt-4 border-t border-slate-50 flex items-center justify-between text-xs text-slate-400 font-medium uppercase tracking-wider">
                    <span className="flex items-center gap-1"><Calendar size={12} /> {post.date}</span>
                    <span className="flex items-center gap-1"><Clock size={12} /> {post.readTime}</span>
                  </div>
                </div>
              </Link>
            ))}
          </div>

          {/* Empty State */}
          {currentPosts.length === 0 && (
              <div className="text-center py-20">
                  <p className="text-xl text-gray-500">No articles found matching your criteria.</p>
                  <button onClick={() => {setSearchQuery(''); setActiveCategory('All');}} className="text-brand-primary mt-4 font-bold underline">Reset Filters</button>
              </div>
          )}

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex justify-center items-center gap-4">
              <Button 
                variant="outline" 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="w-12 h-12 p-0 flex items-center justify-center rounded-full"
              >
                <ChevronLeft size={20} />
              </Button>

              <div className="flex items-center gap-2">
                  {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                      // Logic to show generic page numbers around current
                      let pNum = i + 1;
                      if (totalPages > 5 && currentPage > 3) {
                          pNum = currentPage - 2 + i;
                      }
                      if (pNum > totalPages) return null;

                      return (
                        <button
                            key={pNum}
                            onClick={() => setCurrentPage(pNum)}
                            className={`w-10 h-10 rounded-full text-sm font-bold transition-all ${
                                currentPage === pNum 
                                ? 'bg-brand-primary text-brand-black' 
                                : 'text-gray-500 hover:bg-gray-200'
                            }`}
                        >
                            {pNum}
                        </button>
                      );
                  })}
              </div>

              <Button 
                variant="outline" 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="w-12 h-12 p-0 flex items-center justify-center rounded-full"
              >
                <ChevronRight size={20} />
              </Button>
            </div>
          )}

        </div>
      </section>
    </>
  );
};

export default Insights;

