import React, { useEffect } from 'react';
import { SEO_CONFIG, DEFAULT_SEO } from '../../data/seo';

interface SEOHeadProps {
  title?: string;
  description?: string;
  pageKey?: string; // New: allow looking up meta by key (e.g., 'home', 'about')
}

const SEOHead: React.FC<SEOHeadProps> = ({ title, description, pageKey }) => {
  useEffect(() => {
    let finalTitle = DEFAULT_SEO.title;
    let finalDesc = DEFAULT_SEO.description;

    // 1. If pageKey is provided, lookup in config
    if (pageKey && SEO_CONFIG[pageKey]) {
        finalTitle = SEO_CONFIG[pageKey].title;
        finalDesc = SEO_CONFIG[pageKey].description;
    }

    // 2. Props override config (for dynamic pages like blog posts)
    if (title) finalTitle = title;
    if (description) finalDesc = description;

    // Update Title
    const titleSuffix = " | Onsective Enterprise";
    document.title = finalTitle.includes('|') ? finalTitle : `${finalTitle}${titleSuffix}`;

    // Update Meta Description
    const metaDescription = document.querySelector('meta[name="description"]');
    if (metaDescription) {
      metaDescription.setAttribute('content', finalDesc);
    } else {
      const meta = document.createElement('meta');
      meta.name = "description";
      meta.content = finalDesc;
      document.head.appendChild(meta);
    }

    // Scroll to top on route change
    window.scrollTo(0, 0);
  }, [title, description, pageKey]);

  return null;
};

export default SEOHead;

