const TITLES = [
  "The Future of {kw} in 2026",
  "Mastering {kw}: A Strategic Playbook",
  "Why {kw} Matters for the Fortune 500",
  "10 Strategies for Scaling {kw}",
  "The ROI of {kw} in Modern Business",
  "Navigating the Complexities of {kw}",
  "How to Integrate {kw} into Your Roadmap",
  "The Executive's Guide to {kw}",
  "Case Study: Leveraging {kw} for Growth",
  "Redefining Industry Standards with {kw}",
  "{kw}: The Next Frontier",
  "Optimizing Your {kw} Infrastructure",
  "Overcoming Challenges in {kw} Adoption",
  "Sustainable Approaches to {kw}",
  "The Intersection of {kw} and Business Goals"
];

// Generate 500+ Blog Posts
const generateBlogPosts = (): BlogPost[] => {
  const posts: BlogPost[] = [];
  let id = 1;

  BLOG_TOPICS.forEach((topic) => {
    topic.keywords.forEach((kw) => {
      TITLES.forEach((template, tIdx) => {
        const title = template.replace('{kw}', kw);
        const imageIndex = (id + tIdx) % IMAGES.length;

        posts.push({
          id: `insight-${id}`,
          title: title,
          excerpt: `A comprehensive analysis of how ${kw} is reshaping the ${topic.category} landscape. We dive deep into strategic frameworks and actionable insights for enterprise leaders.`,
          date: ['Feb 2026', 'Jan 2026', 'Dec 2025', 'Nov 2025'][id % 4],
          readTime: `${5 + (id % 10)} min read`,
          category: topic.category,
          image: IMAGES[imageIndex]
        });
        id++;
      });
    });
  });

  return posts;
};

export const ALL_INSIGHTS = generateBlogPosts();
