import React, { Suspense, lazy } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Navbar from './components/Layout/Navbar';
import Footer from './components/Layout/Footer';

// Lazy load pages for performance
const Home = lazy(() => import('./pages/Home'));
const Services = lazy(() => import('./pages/Services'));
const ServiceDetail = lazy(() => import('./pages/ServiceDetail'));
const CapabilityDetail = lazy(() => import('./pages/CapabilityDetail'));
const IndustryDetail = lazy(() => import('./pages/IndustryDetail'));
const Contact = lazy(() => import('./pages/Contact'));
const Insights = lazy(() => import('./pages/Insights'));
const InsightDetail = lazy(() => import('./pages/InsightDetail'));
const Careers = lazy(() => import('./pages/Careers'));
const Events = lazy(() => import('./pages/Events'));
const Admin = lazy(() => import('./pages/Admin'));
const About = lazy(() => import('./pages/About'));
const Investors = lazy(() => import('./pages/Investors'));
const Alumni = lazy(() => import('./pages/Alumni'));
const Platforms = lazy(() => import('./pages/Platforms'));
// Legal Pages
const Privacy = lazy(() => import('./pages/Privacy'));
const Terms = lazy(() => import('./pages/Terms'));
const Copyright = lazy(() => import('./pages/Copyright'));
const Accessibility = lazy(() => import('./pages/Accessibility'));

// Loading Fallback
const Loading = () => (
  <div className="min-h-screen flex items-center justify-center bg-brand-black">
    <div className="w-16 h-16 border-4 border-gray-800 border-t-brand-primary rounded-full animate-spin"></div>
  </div>
);

// Layout Wrapper to hide Nav/Footer on Admin pages
const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const location = useLocation();
    const isAdmin = location.pathname.startsWith('/admin');

    return (
        <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 font-sans antialiased selection:bg-brand-primary selection:text-white">
            {!isAdmin && <Navbar />}
            <main className="flex-grow">
                {children}
            </main>
            {!isAdmin && <Footer />}
        </div>
    );
};

const App: React.FC = () => {
  return (
    <Router>
        <Layout>
          <Suspense fallback={<Loading />}>
            <Routes>
              {/* Main Routes */}
              <Route path="/" element={<Home />} />

              {/* Services & Industries */}
              <Route path="/services" element={<Services />} />
              <Route path="/services/:id" element={<ServiceDetail />} />
              <Route path="/services/:serviceId/capability/:capabilityId" element={<CapabilityDetail />} />
              <Route path="/industries/:id" element={<IndustryDetail />} />

              {/* Products/Platforms */}
              <Route path="/platforms" element={<Platforms />} />

              {/* Insights */}
              <Route path="/insights" element={<Insights />} />
              <Route path="/insights/:id" element={<InsightDetail />} />

              {/* Corporate */}
              <Route path="/about" element={<About />} />
              <Route path="/careers" element={<Careers />} />
              <Route path="/investors" element={<Investors />} />
              <Route path="/alumni" element={<Alumni />} />
              <Route path="/contact" element={<Contact />} />
              <Route path="/events" element={<Events />} />

              {/* Legal */}
              <Route path="/privacy" element={<Privacy />} />
              <Route path="/terms" element={<Terms />} />
              <Route path="/copyright" element={<Copyright />} />
              <Route path="/accessibility" element={<Accessibility />} />

              {/* Admin */}
              <Route path="/admin" element={<Admin />} />

              {/* Fallback */}
              <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
          </Suspense>
        </Layout>
    </Router>
  );
};

export default App;

