import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Search, Globe, ChevronDown, ChevronRight } from 'lucide-react';
import { NAV_ITEMS, COMPANY_NAME } from '../../constants';
import Button from '../UI/Button';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeMega, setActiveMega] = useState<string | null>(null);
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 10);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    setIsOpen(false);
    setActiveMega(null);
  }, [location]);

  const handleMouseEnter = (label: string) => {
    setActiveMega(label);
  };

  const handleMouseLeave = () => {
    setActiveMega(null);
  };

  return (
    <nav 
      className={`fixed w-full z-50 transition-all duration-300 font-sans ${
        scrolled ? 'bg-white shadow-md' : 'bg-white border-b border-gray-100'
      }`}
      onMouseLeave={handleMouseLeave}
    >
      {/* Top Utility Bar - Premium Enterprise Look */}
      <div className="hidden lg:block bg-brand-black text-white text-[11px] font-medium tracking-wide border-b border-gray-800">
        <div className="max-w-[1440px] mx-auto px-6 py-2 flex justify-end items-center gap-6">
          <Link to="/contact" className="hover:text-brand-primary transition-colors">Contact Us</Link>
          <span className="text-gray-600">|</span>
          <Link to="/investors" className="hover:text-brand-primary transition-colors">Investors</Link>
          <span className="text-gray-600">|</span>
          <span className="hover:text-brand-primary cursor-pointer transition-colors flex items-center gap-1"><Globe size={12} /> Global (EN)</span>
        </div>
      </div>

      <div className="max-w-[1440px] mx-auto px-4 sm:px-6 lg:px-8 bg-white relative">
        <div className="flex justify-between items-center h-20">

          {/* Logo */}
          <Link to="/" className="flex items-center gap-3 group z-50 mr-12" aria-label="Go to Home Page">
             <div className="w-10 h-10 bg-brand-black text-white flex items-center justify-center font-serif font-bold text-2xl rounded-sm transition-transform group-hover:scale-105">
              O
            </div>
            <span className="font-sans font-extrabold text-2xl tracking-tighter text-brand-black">
              {COMPANY_NAME}
            </span>
          </Link>

          {/* Desktop Nav - Mega Menu Trigger */}
          <div className="hidden lg:flex flex-1 items-center justify-start h-full">
            {NAV_ITEMS.map((item) => (
              <div 
                key={item.label}
                className="h-full flex items-center"
                onMouseEnter={() => handleMouseEnter(item.label)}
              >
                <Link
                    to={item.path}
                    className={`px-5 text-[13px] font-bold uppercase tracking-widest transition-colors h-full flex items-center border-b-4 border-transparent ${
                        activeMega === item.label ? 'border-brand-primary text-brand-black' : 'text-gray-600 hover:text-brand-primary'
                    } ${location.pathname.startsWith(item.path) && location.pathname !== '/' ? 'text-brand-black' : ''}`}
                >
                    {item.label}
                    {(item.children || item.isMega) && <ChevronDown size={14} className="ml-1 opacity-50" />}
                </Link>
              </div>
            ))}
          </div>

          {/* Search Icon */}
          <div className="hidden lg:flex items-center gap-4">
             <button className="text-brand-black hover:text-brand-primary transition-colors p-2">
                <Search size={20} />
             </button>
          </div>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="lg:hidden p-2 text-brand-black hover:bg-gray-100 rounded-sm"
          >
            {isOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>

        {/* Mega Menu Dropdown Panel */}
        {NAV_ITEMS.map((item) => (
            <div 
                key={item.label}
                className={`absolute left-0 right-0 top-full bg-white border-t border-gray-100 shadow-xl transition-all duration-300 transform origin-top overflow-hidden ${
                    activeMega === item.label && item.children ? 'opacity-100 scale-y-100 visible' : 'opacity-0 scale-y-0 invisible h-0'
                }`}
                onMouseEnter={() => handleMouseEnter(item.label)}
                onMouseLeave={handleMouseLeave}
            >
                <div className="max-w-[1440px] mx-auto px-8 py-12">
                    <div className="flex gap-12">
                        {/* Menu Description / Highlight */}
                        <div className="w-1/4 pr-8 border-r border-gray-100">
                             <h3 className="text-2xl font-serif text-brand-black mb-4">{item.label}</h3>
                             <p className="text-gray-500 text-sm leading-relaxed mb-6">
                                 Explore our {item.label.toLowerCase()} designed to drive global transformation and sustainable growth for the modern enterprise.
                             </p>
                             <Link to={item.path}>
                                 <Button variant="text" withArrow>View All {item.label}</Button>
                             </Link>
                        </div>

                        {/* Menu Items Grid */}
                        <div className="w-3/4 grid grid-cols-3 gap-y-8 gap-x-12">
                            {item.children?.map((child, idx) => (
                                <Link 
                                    key={idx} 
                                    to={child.path} 
                                    className="group block"
                                >
                                    <h4 className="font-bold text-brand-black text-sm mb-2 group-hover:text-brand-primary transition-colors flex items-center">
                                        {child.label}
                                        <ChevronRight size={14} className="ml-1 opacity-0 -translate-x-2 group-hover:opacity-100 group-hover:translate-x-0 transition-all" />
                                    </h4>
                                    {child.description && (
                                        <p className="text-xs text-gray-500 font-light group-hover:text-gray-700 transition-colors">
                                            {child.description}
                                        </p>
                                    )}
                                </Link>
                            ))}
                        </div>
                    </div>
                </div>
                {/* Bottom colored bar for premium feel */}
                <div className="h-1 bg-brand-primary w-full"></div>
            </div>
        ))}

      </div>

      {/* Mobile Menu Overlay */}
      <div 
        className={`fixed inset-0 bg-white z-40 transform transition-transform duration-500 ease-in-out lg:hidden flex flex-col pt-24 px-6 gap-6 overflow-y-auto ${
          isOpen ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        {NAV_ITEMS.map((item) => (
            <div key={item.label} className="border-b border-gray-100 pb-4">
                 <Link
                    to={item.path}
                    className="text-xl font-serif font-bold text-brand-black block mb-2"
                    onClick={() => setIsOpen(false)}
                >
                    {item.label}
                </Link>
                {item.children && (
                    <div className="pl-4 space-y-3 mt-2">
                        {item.children.map((child, idx) => (
                             <Link 
                                key={idx} 
                                to={child.path}
                                className="block text-sm text-gray-600"
                                onClick={() => setIsOpen(false)}
                             >
                                {child.label}
                             </Link>
                        ))}
                    </div>
                )}
            </div>
        ))}
      </div>
    </nav>
  );
};

export default Navbar;

