const ServiceDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();

  // Robust matching: Find service where the URL path slug matches the 'id' param
  // Example: path '/services/strategy' slug is 'strategy'. Matches param 'strategy'.
  const serviceMeta = SERVICES.find(s => {
      const pathSlug = s.path.split('/').pop();
      return pathSlug === id;
  });

  // Use the canonical ID from metadata (e.g. 'it-strategy') to look up content, 
  // ensuring we map 'strategy' (url) -> 'it-strategy' (content key).
  const content = serviceMeta ? SERVICE_CONTENT[serviceMeta.id] : null;

  if (!serviceMeta || !content) {
    return <Navigate to="/services" replace />;
  }

  // Default stats fallback
  const displayStats = content.stats || [
      { value: '30%', label: 'Efficiency Gain', icon: BarChart },
      { value: '99.9%', label: 'Uptime Guarantee', icon: Shield }
  ];

  return (
    <>
      <SEOHead 
        title={serviceMeta.title} 
        description={content.challenge}
      />

      {/* Hero */}
      <section className="relative pt-40 pb-32 bg-brand-black text-white overflow-hidden">
        <div className="absolute inset-0 z-0">
            <img src={content.heroImage} className="w-full h-full object-cover opacity-20" alt="Hero" />
            <div className="absolute inset-0 bg-gradient-to-t from-brand-black via-brand-black/50 to-transparent"></div>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
            <div className="flex items-center gap-3 text-brand-primary font-bold uppercase tracking-widest text-xs mb-6 animate-fade-up">
                <Link to="/services" className="hover:text-white transition-colors">Services</Link> 
                <ArrowRight size={12} /> 
                <span>{serviceMeta.title}</span>
            </div>
            <h1 className="text-5xl md:text-7xl font-serif mb-6 animate-fade-up delay-100">{serviceMeta.title}</h1>
            <p className="text-xl md:text-2xl text-gray-300 font-light max-w-3xl animate-fade-up delay-200">
                {content.tagline}
            </p>
        </div>
      </section>

      {/* The Challenge */}
      <section className="py-24 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">
                <div>
                    <span className="text-brand-primary font-bold tracking-[0.2em] uppercase text-xs mb-4 block">The Challenge</span>
                    <h2 className="text-3xl md:text-4xl font-serif text-brand-black mb-6">Complexity is the Enemy of Speed</h2>
                    <p className="text-gray-600 text-lg leading-relaxed mb-8">
                        {content.challenge}
                    </p>
                    <div className="p-8 bg-brand-gray border-l-4 border-brand-primary italic text-gray-700">
                        "We help organizations navigate this complexity, turning technical debt into technical capital."
                    </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                     {displayStats.map((stat: any, idx: number) => (
                        <div key={idx} className={`rounded-2xl flex flex-col items-center justify-center text-center aspect-square ${
                            idx === 0 
                                ? "bg-brand-black text-white transform translate-y-8" 
                                : "bg-brand-primary/10 text-brand-black"
                        }`}>
                            <stat.icon size={40} className="text-brand-primary mb-4" />
                            <span className="text-3xl font-serif font-bold">{stat.value}</span>
                            <span className="text-xs uppercase tracking-widest mt-2">{stat.label}</span>
                        </div>
                     ))}
                </div>
            </div>
        </div>
      </section>

      {/* Methodology */}
      <section className="py-24 bg-brand-dark text-white">
         <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
             <div className="text-center mb-16">
                 <h2 className="text-3xl md:text-5xl font-serif mb-6">Our Methodology</h2>
                 <p className="text-gray-400 max-w-2xl mx-auto">A proven, rigorous approach to delivery that ensures predictable outcomes.</p>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
                 {content.methodology.map((step: any, idx: number) => (
                     <div key={idx} className="relative p-8 border border-white/10 bg-white/5 hover:bg-white/10 transition-all duration-300 rounded-lg group">
                         <div className="absolute -top-6 left-8 text-6xl font-serif text-brand-primary/20 group-hover:text-brand-primary/40 transition-colors">0{idx + 1}</div>
                         <h3 className="text-xl font-bold mb-4 relative z-10">{step.title}</h3>
                         <p className="text-gray-400 relative z-10 leading-relaxed">{step.desc}</p>
                     </div>
                 ))}
