                      <h2 className="text-4xl font-serif text-brand-black mb-6">Key Capabilities</h2>
                      <p className="text-gray-600 mb-8">
                          Our expertise runs deep. Explore our specific capabilities to see how we drive value in your domain.
                      </p>
                      <Link to="/contact">
                        <Button variant="primary">Discuss Your Needs</Button>
                      </Link>
                  </div>
                  <div className="md:w-2/3 grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {content.capabilities.map((cap: string, idx: number) => {
                          const slug = toSlug(cap);
                          // Determine the service ID from the current URL params or mapping
                          // We pass the current 'id' (e.g. 'strategy') to the URL
                          return (
                            <Link 
                                key={idx} 
                                to={`/services/${id}/capability/${slug}`}
                                className="flex items-center gap-4 p-4 border border-gray-100 shadow-sm hover:shadow-md transition-all bg-white hover:border-brand-primary group"
                            >
                                <div className="w-8 h-8 rounded-full bg-brand-gray flex items-center justify-center group-hover:bg-brand-primary group-hover:text-brand-black transition-colors">
                                    <ArrowRight size={16} className="text-brand-black" />
                                </div>
                                <span className="font-medium text-brand-black group-hover:text-brand-primary transition-colors">{cap}</span>
                            </Link>
                          );
                      })}
                  </div>
              </div>
          </div>
      </section>
    </>
  );
};

