                </div>
                <div className="grid grid-cols-2 gap-6 sm:gap-8">
                     {displayStats.map((stat: any, idx: number) => (
                        <div key={idx} className={`rounded-none flex flex-col items-center justify-center text-center p-8 aspect-square transition-transform hover:scale-105 duration-500 ${
                            idx === 0 
                                ? "bg-brand-black text-white sm:translate-y-12" 
                                : "bg-brand-primary/5 text-brand-black border border-brand-primary/10"
                        }`}>
                            <stat.icon size={44} className="text-brand-primary mb-6" strokeWidth={1.5} />
                            <span className="text-3xl sm:text-4xl font-serif font-bold tracking-tight">{stat.value}</span>
                            <span className="text-[10px] font-black uppercase tracking-[0.2em] mt-3 text-brand-primary/80">{stat.label}</span>
