             <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                 {content.methodology.map((step: any, idx: number) => (
                     <div key={idx} className="relative p-10 border border-white/10 bg-white/5 hover:bg-white/10 hover:border-brand-primary/30 transition-all duration-500 group">
                         <div className="absolute -top-6 left-10 text-7xl font-serif text-brand-primary/10 group-hover:text-brand-primary/20 transition-colors">0{idx + 1}</div>
