                      <span className="text-brand-primary font-bold tracking-[0.3em] uppercase text-[10px] mb-6 block">Intelligence Matrix</span>
                      <h2 className="text-4xl md:text-5xl font-serif text-brand-black mb-8 leading-tight">Key <br className="hidden lg:block"/>Capabilities</h2>
                      <p className="text-slate-500 font-medium mb-10 leading-relaxed">
                          Our expertise runs deep. Explore our specific capabilities to see how we drive value in your specific domain.
                      </p>
                      <Link to="/contact">
                        <Button variant="primary" size="lg" withArrow>Discuss Mission</Button>
                      </Link>
                  </div>
                  <div className="lg:w-2/3 grid grid-cols-1 sm:grid-cols-2 gap-4 h-fit">
                      {content.capabilities.map((cap: string, idx: number) => {
                          const slug = toSlug(cap);
                          return (
                            <Link 
                                key={idx} 
                                to={`/services/${id}/capability/${slug}`}
                                className="flex items-center justify-between p-6 bg-slate-50 border border-slate-100 hover:border-brand-primary hover:bg-white hover:shadow-premium transition-all duration-500 group"
                            >
                                <span className="font-bold text-brand-black uppercase tracking-widest text-[11px] group-hover:text-brand-primary transition-colors pr-4">{cap}</span>
                                <div className="w-10 h-10 bg-brand-black text-brand-primary flex items-center justify-center shrink-0 group-hover:bg-brand-primary group-hover:text-brand-black transition-all duration-500">
                                    <ArrowRight size={18} />
                                </div>
                            </Link>
                          );
                      })}
                  </div>
              </div>
          </div>
      </section>
    </>
  );
};

