import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Search, Globe, ChevronDown } from 'lucide-react';
import { NAV_ITEMS, COMPANY_NAME } from '../../constants';
import Button from '../UI/Button';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeMega, setActiveMega] = useState<string | null>(null);
  const location = useLocation();

  // Determine if we should use a dark or light theme based on the current page and scroll state
  const isTransparentHeroPage = ['/', '/services', '/about', '/careers', '/contact'].includes(location.pathname);
  const navTheme = (!scrolled && isTransparentHeroPage && !isOpen) ? 'dark' : 'light';

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    setIsOpen(false);
    setActiveMega(null);
  }, [location]);

  // Prevent scroll when mobile menu is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  return (
    <nav 
      className={`fixed w-full z-[100] transition-all duration-500 font-sans border-b ${
        navTheme === 'dark' 
          ? 'bg-transparent border-transparent py-4 md:py-6' 
          : 'bg-white/95 backdrop-blur-xl shadow-premium border-slate-100 py-0'
      }`}
      onMouseLeave={() => setActiveMega(null)}
    >
      {/* Top Utility Bar (Desktop Only) */}
      <div className={`hidden lg:block transition-all duration-500 overflow-hidden ${scrolled ? 'h-0 opacity-0' : 'h-8 opacity-100'} bg-brand-black text-white text-[10px] font-bold tracking-widest border-b border-white/5 uppercase`}>
        <div className="max-w-[1440px] mx-auto px-6 h-full flex justify-end items-center gap-8">
          <Link to="/contact" className="hover:text-brand-primary transition-colors">Support</Link>
          <Link to="/investors" className="hover:text-brand-primary transition-colors">Investors</Link>
          <span className="hover:text-brand-primary cursor-pointer transition-colors flex items-center gap-1.5"><Globe size={11} /> Global (EN)</span>
        </div>
      </div>

      <div className="max-w-[1440px] mx-auto px-4 sm:px-6 lg:px-8 relative">
        <div className="flex justify-between items-center h-20 md:h-24">

          {/* Logo Section */}
          <Link to="/" className="flex items-center gap-3 md:gap-4 group z-[110]" aria-label="Go to Home Page">
             <div className={`w-9 h-9 md:w-11 md:h-11 flex items-center justify-center font-serif font-bold text-xl md:text-2xl border transition-all duration-500 ${
               navTheme === 'dark' 
                ? 'bg-white text-brand-black border-white/20' 
                : 'bg-brand-black text-brand-primary border-brand-primary/20 shadow-lg'
             } group-hover:scale-110 group-hover:bg-brand-primary group-hover:text-brand-black`}>
              O
            </div>
            <span className={`font-sans font-extrabold text-xl md:text-2xl tracking-tighter transition-colors duration-500 ${
              navTheme === 'dark' ? 'text-white' : 'text-brand-black'
            }`}>
              {COMPANY_NAME.toUpperCase()}
            </span>
          </Link>

          {/* Desktop Navigation Links */}
          <div className="hidden lg:flex flex-1 items-center justify-center h-full ml-12">
            {NAV_ITEMS.map((item) => (
              <div 
                key={item.label}
                className="h-full flex items-center"
                onMouseEnter={() => setActiveMega(item.label)}
              >
                <Link
                    to={item.path}
                    className={`px-6 text-[12px] font-bold uppercase tracking-[0.2em] transition-all duration-300 h-full flex items-center relative group ${
                        navTheme === 'dark' ? 'text-white/80' : 'text-slate-600'
                    } hover:text-brand-primary`}
                >
                    {item.label}
                    {(item.children || item.isMega) && <ChevronDown size={14} className={`ml-1 transition-transform duration-300 ${activeMega === item.label ? 'rotate-180' : ''}`} />}

                    {/* Hover Underline Effect */}
                    <span className={`absolute bottom-0 left-1/2 -translate-x-1/2 w-0 h-1 bg-brand-primary transition-all duration-300 ${
                      activeMega === item.label ? 'w-full' : ''
                    }`}></span>
                </Link>
              </div>
            ))}
          </div>

          {/* Desktop CTA & Search */}
          <div className="hidden lg:flex items-center gap-8">
             <button className={`transition-colors duration-500 ${navTheme === 'dark' ? 'text-white' : 'text-brand-black'} hover:text-brand-primary`}>
                <Search size={20} />
             </button>
             <Link to="/contact">
                <Button variant={navTheme === 'dark' ? 'outline' : 'primary'} size="sm" className={navTheme === 'dark' ? 'border-white text-white hover:bg-white hover:text-brand-black' : ''}>
                  Get Started
                </Button>
             </Link>
          </div>

          {/* Mobile/Tablet Menu Toggle */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className={`lg:hidden p-3 rounded-none z-[110] transition-all duration-300 border ${
              isOpen 
                ? 'text-brand-black bg-white border-slate-200 rotate-180' 
                : (navTheme === 'dark' ? 'text-white bg-white/10 border-white/20' : 'text-brand-black bg-slate-100 border-slate-200')
            }`}
            aria-expanded={isOpen}
            aria-label="Toggle navigation menu"
          >
            {isOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>

        {/* Desktop Mega Menu Dropdowns */}
        {NAV_ITEMS.map((item) => (
            <div 
                key={item.label}
                className={`hidden lg:block absolute left-0 right-0 top-full bg-white shadow-2xl transition-all duration-500 transform ${
                    activeMega === item.label && (item.children || item.isMega) ? 'opacity-100 translate-y-0 visible' : 'opacity-0 -translate-y-4 invisible'
                }`}
                onMouseEnter={() => setActiveMega(item.label)}
            >
                <div className="max-w-[1440px] mx-auto px-8 py-16 grid grid-cols-1 lg:grid-cols-12 gap-16">
                    <div className="lg:col-span-4 border-r border-slate-100 pr-12">
                         <span className="text-brand-primary font-bold text-[10px] tracking-[0.3em] uppercase mb-4 block">Section</span>
                         <h3 className="text-4xl font-serif text-brand-black mb-6">{item.label}</h3>
                         <p className="text-slate-500 text-sm leading-relaxed mb-10 font-medium">
                            Architecting bespoke solutions for the world's most sophisticated enterprises. Explore our {item.label.toLowerCase()} framework.
                         </p>
                         <Link to={item.path}>
                             <Button variant="text" withArrow className="font-bold">Explore Overview</Button>
                         </Link>
                    </div>

                    <div className="lg:col-span-8 grid grid-cols-2 gap-y-10 gap-x-12">
                        {item.children?.map((child, idx) => (
                            <Link key={idx} to={child.path} className="group block">
                                <div className="flex items-start gap-4">
                                  <div className="w-8 h-[2px] bg-brand-primary mt-2 scale-x-0 group-hover:scale-x-100 transition-transform origin-left duration-300"></div>
                                  <div>
                                    <h4 className="font-bold text-brand-black text-[13px] uppercase tracking-widest mb-2 group-hover:text-brand-primary transition-colors">
                                        {child.label}
                                    </h4>
                                    {child.description && (
                                        <p className="text-[11px] text-slate-400 font-bold uppercase tracking-wider group-hover:text-slate-600 transition-colors">
                                            {child.description}
                                        </p>
                                    )}
                                  </div>
                                </div>
                            </Link>
                        ))}
                    </div>
                </div>
                <div className="h-1.5 w-full bg-gold-gradient"></div>
            </div>
        ))}
      </div>

      {/* Mobile/Tablet Fullscreen Menu Overlay */}
      <div 
        className={`fixed inset-0 bg-white z-[100] transition-all duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] lg:hidden flex flex-col ${
          isOpen ? 'translate-x-0 opacity-100 pointer-events-auto' : 'translate-x-full opacity-0 pointer-events-none'
        }`}
      >
        <div className="flex flex-col h-full pt-32 sm:pt-40 px-6 sm:px-16 pb-12 overflow-y-auto">
          {NAV_ITEMS.map((item, idx) => (
            <div key={item.label} className={`mb-8 sm:mb-12 ${isOpen ? 'animate-fade-up' : ''}`} style={{ animationDelay: `${idx * 0.05}s` }}>
                 <Link
                    to={item.path}
                    className="text-4xl sm:text-5xl font-serif font-bold text-brand-black hover:text-brand-primary transition-colors block mb-4"
                    onClick={() => setIsOpen(false)}
                >
                    {item.label}
                </Link>
                {item.children && (
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-12 gap-y-4 pl-4 border-l-2 border-brand-primary/20">
                        {item.children.map((child, cIdx) => (
                             <Link 
                                key={cIdx} 
                                to={child.path}
                                className="text-[11px] sm:text-xs font-bold uppercase tracking-[0.2em] text-slate-500 hover:text-brand-primary transition-colors"
                                onClick={() => setIsOpen(false)}
                             >
                                {child.label}
                             </Link>
                        ))}
                    </div>
                )}
            </div>
          ))}

          <div className="mt-auto pt-10 sm:pt-16 border-t border-slate-100 flex flex-col gap-6">
              <Link to="/contact" onClick={() => setIsOpen(false)}>
                <Button variant="primary" className="w-full text-center py-6 text-sm" size="lg">Initiate Engagement</Button>
              </Link>
              <div className="flex justify-between items-center text-[10px] sm:text-xs font-bold uppercase tracking-[0.3em] text-slate-400">
                <span>© 2026 ONSECTIVE ENTERPRISE</span>
                <div className="flex items-center gap-2"><Globe size={14} /> GLOBAL</div>
              </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

