import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Search, Globe, ChevronDown } from 'lucide-react';
import { NAV_ITEMS, COMPANY_NAME } from '../../constants';
import Button from '../UI/Button';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeMega, setActiveMega] = useState<string | null>(null);
  const location = useLocation();

  const isDarkHeroPage = ['/', '/services', '/about', '/careers'].includes(location.pathname);
  const navTheme = (!scrolled && isDarkHeroPage && !isOpen) ? 'dark' : 'light';

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 40);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    setIsOpen(false);
    setActiveMega(null);
  }, [location]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  return (
    <nav 
      className={`fixed top-0 left-0 right-0 w-full z-[100] transition-all duration-500 border-b ${
        navTheme === 'dark' 
          ? 'bg-transparent border-transparent py-4 md:py-6' 
          : 'bg-white/95 backdrop-blur-xl shadow-premium border-slate-100 py-0'
      }`}
      onMouseLeave={() => setActiveMega(null)}
    >
      <div className="w-full max-w-[1440px] mx-auto px-4 sm:px-6 lg:px-12">
        <div className="flex justify-between items-center h-16 md:h-24">

          {/* Elite Logo Branding */}
          <Link to="/" className="flex items-center gap-2 sm:gap-4 z-[110] group" aria-label="Home">
            <div className={`w-8 h-8 sm:w-11 sm:h-11 flex items-center justify-center font-serif font-bold text-lg sm:text-2xl border transition-all duration-500 ${
               navTheme === 'dark' 
                ? 'bg-white text-brand-black border-white/20' 
                : 'bg-brand-black text-brand-primary border-brand-primary/20 shadow-lg'
             } group-hover:scale-110 group-hover:bg-brand-primary group-hover:text-brand-black`}>
              O
            </div>
            <span className={`font-sans font-extrabold text-lg sm:text-2xl tracking-tighter transition-colors duration-500 ${
              navTheme === 'dark' ? 'text-white' : 'text-brand-black'
            }`}>
              {COMPANY_NAME.toUpperCase()}
            </span>
          </Link>

          {/* Desktop Navigation */}
          <div className="hidden lg:flex flex-1 items-center justify-center h-full ml-12">
            {NAV_ITEMS.map((item) => (
              <div 
                key={item.label}
                className="h-full flex items-center"
                onMouseEnter={() => setActiveMega(item.label)}
              >
                <Link
                    to={item.path}
                    className={`px-6 text-[11px] font-bold uppercase tracking-[0.2em] transition-all duration-300 h-full flex items-center relative group ${
                        navTheme === 'dark' ? 'text-white/80' : 'text-slate-600'
                    } hover:text-brand-primary`}
                >
                    {item.label}
                    {item.children && <ChevronDown size={12} className={`ml-1 transition-transform duration-300 ${activeMega === item.label ? 'rotate-180' : ''}`} />}
                    <span className={`absolute bottom-0 left-1/2 -translate-x-1/2 w-0 h-1 bg-brand-primary transition-all duration-300 ${
                      activeMega === item.label ? 'w-full' : ''
                    }`}></span>
                </Link>
              </div>
            ))}
          </div>

          {/* Desktop Actions */}
          <div className="hidden lg:flex items-center gap-6">
             <button className={`transition-colors duration-500 ${navTheme === 'dark' ? 'text-white' : 'text-brand-black'} hover:text-brand-primary`}>
                <Search size={20} />
             </button>
             <Link to="/contact">
                <Button variant={navTheme === 'dark' ? 'outline' : 'primary'} size="sm" className={navTheme === 'dark' ? 'border-white text-white hover:bg-white hover:text-brand-black' : ''}>
                  Initiate Engagement
                </Button>
             </Link>
          </div>

          {/* Mobile/Tablet Menu Toggle - Robust Fixed Positioning */}
          <div className="flex items-center gap-3 lg:hidden z-[110]">
             {!isOpen && (
                <button className={`p-2 transition-colors ${navTheme === 'dark' ? 'text-white' : 'text-brand-black'}`}>
                  <Search size={20} />
                </button>
             )}
            <button
              onClick={() => setIsOpen(!isOpen)}
              className={`p-3 rounded-none transition-all duration-300 border ${
                isOpen 
                  ? 'text-brand-black bg-white border-slate-200 rotate-180' 
                  : (navTheme === 'dark' ? 'text-white bg-white/10 border-white/20' : 'text-brand-black bg-slate-100 border-slate-200')
              }`}
              aria-expanded={isOpen}
              aria-label="Menu"
            >
              {isOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>

      {/* Desktop Mega Menu (Hidden on Mobile) */}
      <div className="hidden lg:block">
        {NAV_ITEMS.map((item) => (
            <div 
                key={item.label}
                className={`absolute left-0 right-0 top-full bg-white shadow-2xl transition-all duration-500 transform ${
                    activeMega === item.label && item.children ? 'opacity-100 translate-y-0 visible' : 'opacity-0 -translate-y-4 invisible'
                }`}
                onMouseEnter={() => setActiveMega(item.label)}
            >
                <div className="max-w-[1440px] mx-auto px-12 py-12 grid grid-cols-12 gap-12">
                    <div className="col-span-4 border-r border-slate-100 pr-12">
                         <span className="text-brand-primary font-bold text-[10px] tracking-[0.3em] uppercase mb-4 block">Navigation</span>
                         <h3 className="text-4xl font-serif text-brand-black mb-6">{item.label}</h3>
                         <p className="text-slate-500 text-sm leading-relaxed mb-8 font-medium">
                            Architecting bespoke solutions for the world's most sophisticated enterprises.
                         </p>
                         <Link to={item.path}>
                             <Button variant="text" withArrow className="font-bold">Explore Overview</Button>
                         </Link>
                    </div>
                    <div className="col-span-8 grid grid-cols-2 gap-x-8 gap-y-6">
                        {item.children?.map((child, idx) => (
                            <Link key={idx} to={child.path} className="group block p-4 hover:bg-slate-50 transition-colors">
                                <h4 className="font-bold text-brand-black text-[11px] uppercase tracking-widest mb-1 group-hover:text-brand-primary transition-colors">
                                    {child.label}
                                </h4>
                                {child.description && (
                                    <p className="text-[10px] text-slate-400 font-medium uppercase truncate">
                                        {child.description}
                                    </p>
                                )}
                            </Link>
                        ))}
                    </div>
                </div>
                <div className="h-1 w-full bg-gold-gradient"></div>
            </div>
        ))}
      </div>

      {/* Fullscreen Mobile/Tablet Menu Overlay */}
      <div 
        className={`fixed inset-0 bg-white z-[100] transition-all duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] lg:hidden flex flex-col ${
          isOpen ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0 pointer-events-none'
        }`}
      >
        <div className="flex flex-col h-full pt-24 sm:pt-32 px-6 sm:px-12 pb-12 overflow-y-auto">
          <div className="space-y-6 sm:space-y-8">
            {NAV_ITEMS.map((item, idx) => (
              <div key={item.label} className={`${isOpen ? 'animate-fade-up' : ''}`} style={{ animationDelay: `${idx * 0.05}s` }}>
                   <Link
                      to={item.path}
                      className="text-3xl sm:text-5xl font-serif font-bold text-brand-black hover:text-brand-primary transition-colors flex items-center justify-between group"
                      onClick={() => setIsOpen(false)}
                  >
                      {item.label}
                      <span className="w-12 h-[1px] bg-slate-200 group-hover:bg-brand-primary transition-colors hidden sm:block"></span>
                  </Link>
                  {item.children && (
                      <div className="mt-4 grid grid-cols-1 sm:grid-cols-2 gap-3 pl-4 border-l-2 border-brand-primary/20">
                          {item.children.slice(0, 6).map((child, cIdx) => (
                               <Link 
                                  key={cIdx} 
                                  to={child.path}
                                  className="text-[10px] sm:text-xs font-bold uppercase tracking-[0.2em] text-slate-500 hover:text-brand-primary py-1"
                                  onClick={() => setIsOpen(false)}
                               >
                                  {child.label}
                               </Link>
                          ))}
                      </div>
                  )}
              </div>
            ))}
          </div>

          <div className="mt-auto pt-10 sm:pt-16 border-t border-slate-100 space-y-8">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <Link to="/contact" onClick={() => setIsOpen(false)}>
                    <Button variant="primary" className="w-full text-center py-5 text-xs sm:text-sm">Initiate Mission</Button>
                  </Link>
                  <Link to="/services" onClick={() => setIsOpen(false)} className="hidden sm:block">
                    <Button variant="outline" className="w-full text-center py-5 text-sm">Capabilities</Button>
                  </Link>
              </div>
              <div className="flex justify-between items-center text-[9px] sm:text-xs font-bold uppercase tracking-[0.3em] text-slate-400">
                <span>© 2026 ONSECTIVE ENTERPRISE</span>
                <div className="flex items-center gap-2"><Globe size={14} /> EN-GLOBAL</div>
              </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

