                isOpen || navTheme === 'light'
                  ? 'bg-brand-black text-brand-primary border-brand-primary/20'
                  : 'bg-white text-brand-black border-white/20'
              } group-hover:scale-105 group-hover:bg-brand-primary group-hover:text-brand-black`}>
                O
              </div>
              <span className={`font-sans font-black text-lg md:text-2xl tracking-tighter transition-colors duration-500 ${
                isOpen || navTheme === 'light' ? 'text-brand-black' : 'text-white'
              }`}>
                {COMPANY_NAME.toUpperCase()}
              </span>
            </Link>

            {/* Desktop Link Grid */}
            <div className="hidden lg:flex flex-1 items-center justify-center h-full ml-12">
              {NAV_ITEMS.map((item) => (
                <div 
                  key={item.label}
                  className="h-full flex items-center"
                  onMouseEnter={() => setActiveMega(item.label)}
                >
                  <Link
                    to={item.path}
                    className={`px-6 text-[11px] font-bold uppercase tracking-[0.25em] transition-all duration-300 h-full flex items-center relative group ${
                        navTheme === 'dark' ? 'text-white/80' : 'text-slate-600'
                    } hover:text-brand-primary`}
                  >
                    {item.label}
                    {item.children && <ChevronDown size={12} className={`ml-1 transition-transform ${activeMega === item.label ? 'rotate-180' : ''}`} />}
                    <span className={`absolute bottom-0 left-1/2 -translate-x-1/2 w-0 h-1 bg-brand-primary transition-all duration-500 ${
                      activeMega === item.label ? 'w-full' : ''
                    }`}></span>
                  </Link>
                </div>
              ))}
            </div>

            {/* Right Actions */}
            <div className="flex items-center gap-4 md:gap-8 z-[310]">
              <button className={`hidden md:block transition-colors ${
                isOpen || navTheme === 'light' ? 'text-brand-black' : 'text-white'
              } hover:text-brand-primary`}>
                <Search size={22} />
              </button>

              <Link to="/contact" className="hidden lg:block">
                <Button variant={navTheme === 'dark' ? 'outline' : 'primary'} size="sm" className={navTheme === 'dark' ? 'border-white text-white' : ''}>
                  Consultation
                </Button>
              </Link>

              {/* Mobile Trigger - Fixed Contrast */}
              <button
                onClick={() => setIsOpen(!isOpen)}
                className={`p-3 rounded-none transition-all duration-500 border ${
                  isOpen 
                    ? 'bg-brand-primary text-brand-black border-brand-primary' 
                    : (navTheme === 'dark' ? 'bg-white/10 text-white border-white/20' : 'bg-slate-100 text-brand-black border-slate-200')
                }`}
                aria-label="Toggle Menu"
              >
                {isOpen ? <X size={24} /> : <Menu size={24} />}
              </button>
            </div>
          </div>
        </div>

        {/* Desktop Mega Dropdown */}
        <div 
            className={`hidden lg:block absolute left-0 right-0 top-full bg-white shadow-2xl transition-all duration-500 transform border-t border-slate-100 ${
                activeMega && NAV_ITEMS.find(i => i.label === activeMega)?.children ? 'opacity-100 translate-y-0 visible' : 'opacity-0 -translate-y-4 invisible'
            }`}
            onMouseEnter={() => setActiveMega(activeMega)}
            onMouseLeave={() => setActiveMega(null)}
        >
            <div className="max-w-[1440px] mx-auto px-12 py-16 grid grid-cols-12 gap-12">
