      <div 
        className={`fixed inset-0 w-full h-screen bg-brand-black z-[250] transition-all duration-700 ease-[cubic-bezier(0.85,0,0.15,1)] flex flex-col ${
          isOpen ? 'translate-y-0 opacity-100 pointer-events-auto' : '-translate-y-full opacity-0 pointer-events-none'
        }`}
      >
        <div className="flex flex-col h-full pt-28 sm:pt-40 px-6 sm:px-16 pb-12 overflow-y-auto">
          <div className="space-y-10 sm:space-y-12 mb-20">
            {NAV_ITEMS.map((item, idx) => (
              <div 
                key={item.label} 
                className={`transition-all duration-700 transform ${isOpen ? 'translate-x-0 opacity-100' : '-translate-x-8 opacity-0'}`}
                style={{ transitionDelay: `${100 + (idx * 80)}ms` }}
              >
                <Link
                  to={item.path}
                  className="text-4xl sm:text-6xl font-serif font-black text-white hover:text-brand-primary transition-colors inline-block uppercase tracking-tighter"
