import { BlogPost } from '../types';
import { ASSETS } from '../utils/assets';

const IMAGES = [
  ASSETS.BLOG_1,
  ASSETS.BLOG_2,
  ASSETS.BLOG_3,
  ASSETS.BLOG_4,
  ASSETS.BLOG_5,
  ASSETS.BLOG_6,
  ASSETS.BLOG_7,
  ASSETS.BLOG_8,
];

const BLOG_TOPICS = [
  {
    category: 'Artificial Intelligence',
    keywords: ['Generative AI', 'LLMs', 'Neural Networks', 'Predictive Analytics', 'Machine Learning']
  },
  {
    category: 'Digital Strategy',
    keywords: ['Omnichannel Growth', 'Customer Journey', 'MarTech Stack', 'Growth Hacking']
  },
  {
    category: 'Technical Authority',
    keywords: ['Technical SEO', 'Core Web Vitals', 'Search Logic', 'Authority Building']
  },
  {
    category: 'Brand Stewardship',
    keywords: ['Brand Identity', 'Storytelling', 'Crisis Management', 'Identity Systems']
  }
];

const TITLES = [
  "Understanding {kw} in 2026",
  "A Leader's Guide to {kw}",
  "How {kw} Drives Business Value",
  "The Practical Impact of {kw}",
  "Simplifying {kw} for the Modern CEO"
];

const generateBlogPosts = (): BlogPost[] => {
  const posts: BlogPost[] = [];
  let id = 1;

  BLOG_TOPICS.forEach((topic) => {
    topic.keywords.forEach((kw) => {
      TITLES.forEach((template, tIdx) => {
        const title = template.replace('{kw}', kw);
        const imageIndex = (id + tIdx) % IMAGES.length;

        posts.push({
          id: `insight-${id}`,
          title: title,
          excerpt: `In this article, we explain how ${kw} helps businesses grow. We focus on clear steps and real-world benefits so you can make better decisions for your team.`,
          date: ['Feb 2026', 'Jan 2026', 'Dec 2025', 'Nov 2025'][id % 4],
          readTime: `${5 + (id % 5)} min read`,
          category: topic.category,
          image: IMAGES[imageIndex]
        });
        id++;
      });
    });
  });

  return posts;
};

export const ALL_INSIGHTS = generateBlogPosts();
export const LATEST_INSIGHTS = ALL_INSIGHTS.slice(0, 9);

