  USERS: 'onsective_personnel',
  POSTS: 'onsective_briefs',
  LEADS: 'onsective_leads',
  AUTH: 'onsective_session'
};

const initializeDB = () => {
  if (!localStorage.getItem(DB_KEYS.USERS)) {
    localStorage.setItem(DB_KEYS.USERS, JSON.stringify([
      { id: '1', username: 'admin', password: 'admin', role: 'Superuser', name: 'System Administrator' }
    ]));
  }
  if (!localStorage.getItem(DB_KEYS.POSTS)) {
    localStorage.setItem(DB_KEYS.POSTS, JSON.stringify([]));
  }
};

const Admin: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'posts' | 'users' | 'leads'>('dashboard');
  const [currentUser, setCurrentUser] = useState<any>(null);

  // Form States
  const [loginData, setLoginData] = useState({ username: '', password: '' });
  const [postData, setPostData] = useState({ title: '', category: '', excerpt: '', content: '' });
  const [userData, setUserData] = useState({ username: '', password: '', role: 'Analyst', name: '' });

  // DB States
  const [users, setUsers] = useState<any[]>([]);
  const [posts, setPosts] = useState<any[]>([]);
  const [leads, setLeads] = useState<any[]>([]);
  const [error, setError] = useState('');

  useEffect(() => {
    initializeDB();
    const session = localStorage.getItem(DB_KEYS.AUTH);
    if (session) {
      setIsAuthenticated(true);
      setCurrentUser(JSON.parse(session));
    }
    syncData();
  }, []);

  const syncData = () => {
    setUsers(JSON.parse(localStorage.getItem(DB_KEYS.USERS) || '[]'));
    setPosts(JSON.parse(localStorage.getItem(DB_KEYS.POSTS) || '[]'));
    // Pull leads from contact form logic if implemented in localStorage elsewhere, 
    // but here we manage them locally for the portal.
    setLeads(JSON.parse(localStorage.getItem(DB_KEYS.LEADS) || '[]'));
  };

  // --- AUTH ACTIONS ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const storedUsers = JSON.parse(localStorage.getItem(DB_KEYS.USERS) || '[]');
    const user = storedUsers.find((u: any) => u.username === loginData.username && u.password === loginData.password);

    if (user) {
      setIsAuthenticated(true);
      setCurrentUser(user);
      localStorage.setItem(DB_KEYS.AUTH, JSON.stringify(user));
      setError('');
    } else {
      setError('Invalid Intelligence Credentials.');
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    localStorage.removeItem(DB_KEYS.AUTH);
  };

  // --- CONTENT ACTIONS ---
  const handlePostSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newPost = { ...postData, id: `brief-${Date.now()}`, date: new Date().toLocaleDateString() };
    const updatedPosts = [newPost, ...posts];
    localStorage.setItem(DB_KEYS.POSTS, JSON.stringify(updatedPosts));
    setPosts(updatedPosts);
    setPostData({ title: '', category: '', excerpt: '', content: '' });
    alert('Intelligence Brief Synchronized.');
