import React, { useState, useEffect } from 'react';
import { 
  PenTool, Save, Eye, LayoutDashboard, FileText, Settings, 
  LogOut, Users, MessageSquare, ShieldAlert, Trash2, UserPlus,
  CheckCircle, AlertCircle, Lock, Key, BarChart3, Menu, X
} from 'lucide-react';
import Button from '../components/UI/Button';

const DB_KEYS = {
  USERS: 'onsective_personnel',
  POSTS: 'onsective_briefs',
  LEADS: 'onsective_leads',
  AUTH: 'onsective_session'
};

const initializeDB = () => {
  if (!localStorage.getItem(DB_KEYS.USERS)) {
    localStorage.setItem(DB_KEYS.USERS, JSON.stringify([
      { id: '1', username: 'admin', password: 'admin', role: 'Superuser', name: 'System Administrator' }
    ]));
  }
};

const Admin: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'posts' | 'users' | 'leads'>('dashboard');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [loginData, setLoginData] = useState({ username: '', password: '' });
  const [postData, setPostData] = useState({ title: '', category: '', excerpt: '', content: '' });
  const [userData, setUserData] = useState({ username: '', password: '', role: 'Analyst', name: '' });

  const [users, setUsers] = useState<any[]>([]);
  const [posts, setPosts] = useState<any[]>([]);
  const [leads, setLeads] = useState<any[]>([]);
  const [error, setError] = useState('');

  useEffect(() => {
    initializeDB();
    const session = localStorage.getItem(DB_KEYS.AUTH);
    if (session) {
      setIsAuthenticated(true);
      setCurrentUser(JSON.parse(session));
    }
    syncData();
  }, []);

  const syncData = () => {
    setUsers(JSON.parse(localStorage.getItem(DB_KEYS.USERS) || '[]'));
    setPosts(JSON.parse(localStorage.getItem(DB_KEYS.POSTS) || '[]'));
    setLeads(JSON.parse(localStorage.getItem(DB_KEYS.LEADS) || '[]'));
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const storedUsers = JSON.parse(localStorage.getItem(DB_KEYS.USERS) || '[]');
    const user = storedUsers.find((u: any) => u.username === loginData.username && u.password === loginData.password);

    if (user) {
      setIsAuthenticated(true);
      setCurrentUser(user);
      localStorage.setItem(DB_KEYS.AUTH, JSON.stringify(user));
      setError('');
    } else {
      setError('Invalid Intelligence Credentials.');
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    localStorage.removeItem(DB_KEYS.AUTH);
  };

  const handlePostSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newPost = { ...postData, id: `brief-${Date.now()}`, date: new Date().toLocaleDateString() };
    const updatedPosts = [newPost, ...posts];
    localStorage.setItem(DB_KEYS.POSTS, JSON.stringify(updatedPosts));
    setPosts(updatedPosts);
    setPostData({ title: '', category: '', excerpt: '', content: '' });
  };

  const deleteUser = (id: string) => {
    if (id === '1') return alert('Cannot revoke Superuser privileges.');
    const updated = users.filter(u => u.id !== id);
    localStorage.setItem(DB_KEYS.USERS, JSON.stringify(updated));
    setUsers(updated);
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-brand-black flex items-center justify-center p-4">
        <div className="w-full max-w-md bg-slate-900 border border-white/10 p-8 sm:p-12 shadow-2xl">
          <div className="text-center mb-10">
            <div className="w-16 h-16 sm:w-20 sm:h-20 bg-brand-primary text-brand-black flex items-center justify-center font-serif font-bold text-3xl sm:text-4xl mx-auto mb-6">O</div>
            <h1 className="text-white text-xl sm:text-2xl font-serif font-black tracking-tight mb-2 uppercase">Command Access</h1>
            <p className="text-slate-500 text-[8px] sm:text-[10px] font-black uppercase tracking-[0.3em]">Institutional Verification Required</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            {error && (
              <div className="p-4 bg-red-900/20 border border-red-900/50 text-red-400 text-[9px] sm:text-[10px] font-bold uppercase tracking-widest flex items-center gap-3">
                <ShieldAlert size={14} /> {error}
              </div>
            )}
            <div className="space-y-2">
              <label className="text-[9px] sm:text-[10px] font-black text-slate-400 uppercase tracking-widest block">Personnel ID</label>
              <div className="relative">
                <input type="text" required className="w-full bg-black/40 border border-white/10 p-4 text-white focus:border-brand-primary outline-none transition-all pl-12" value={loginData.username} onChange={(e) => setLoginData({...loginData, username: e.target.value})} />
                <Users size={18} className="absolute left-4 top-4 text-slate-600" />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[9px] sm:text-[10px] font-black text-slate-400 uppercase tracking-widest block">Security Key</label>
              <div className="relative">
                <input type="password" required className="w-full bg-black/40 border border-white/10 p-4 text-white focus:border-brand-primary outline-none transition-all pl-12" value={loginData.password} onChange={(e) => setLoginData({...loginData, password: e.target.value})} />
                <Key size={18} className="absolute left-4 top-4 text-slate-600" />
