import React, { useState, useEffect, useMemo } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Search, Globe, ChevronDown, ArrowRight } from 'lucide-react';
import { NAV_ITEMS, COMPANY_NAME, SERVICES, INDUSTRIES, ALL_INSIGHTS } from '../../constants';
import Button from '../UI/Button';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeMega, setActiveMega] = useState<string | null>(null);
  const location = useLocation();

  const isDarkHeroPage = ['/', '/services', '/about', '/careers'].includes(location.pathname);
  const navTheme = (!scrolled && isDarkHeroPage && !isOpen) ? 'dark' : 'light';

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    setIsOpen(false);
    setIsSearchOpen(false);
    setActiveMega(null);
  }, [location.pathname]);

  // Global Search Logic
  const searchResults = useMemo(() => {
    if (searchQuery.length < 2) return null;
    const q = searchQuery.toLowerCase();
    return {
      services: SERVICES.filter(s => s.title.toLowerCase().includes(q)),
      industries: INDUSTRIES.filter(i => i.title.toLowerCase().includes(q)),
      insights: ALL_INSIGHTS.filter(p => p.title.toLowerCase().includes(q)).slice(0, 5)
    };
  }, [searchQuery]);

  return (
    <>
      <nav 
        className={`fixed top-0 left-0 w-full z-[300] transition-all duration-700 ${
          navTheme === 'dark' 
            ? 'bg-transparent py-4 md:py-6' 
            : 'bg-white/95 backdrop-blur-2xl shadow-premium border-b border-slate-100 py-0'
        }`}
      >
        <div className="w-full max-w-[1440px] mx-auto px-4 sm:px-10 lg:px-12">
          <div className="flex justify-between items-center h-16 md:h-24">

            <Link to="/" className="flex items-center gap-2 md:gap-3 z-[310] group" aria-label="Home">
              <div className={`w-8 h-8 md:w-11 md:h-11 flex items-center justify-center font-serif font-bold text-lg md:text-2xl border transition-all duration-500 ${
                isOpen || navTheme === 'light'
                  ? 'bg-brand-black text-brand-primary border-brand-primary/20'
                  : 'bg-white text-brand-black border-white/20'
              } group-hover:scale-105 group-hover:bg-brand-primary group-hover:text-brand-black`}>
                O
              </div>
              <span className={`font-sans font-black text-sm md:text-2xl tracking-tighter transition-colors duration-500 ${
                isOpen || navTheme === 'light' ? 'text-brand-black' : 'text-white'
              }`}>
                {COMPANY_NAME.toUpperCase()}
              </span>
            </Link>

            <div className="hidden lg:flex flex-1 items-center justify-center h-full ml-12">
              {NAV_ITEMS.map((item) => (
                <div 
                  key={item.label}
                  className="h-full flex items-center"
                  onMouseEnter={() => setActiveMega(item.label)}
                >
                  <Link
                    to={item.path}
                    className={`px-6 text-[11px] font-bold uppercase tracking-[0.25em] transition-all duration-300 h-full flex items-center relative group ${
                        navTheme === 'dark' ? 'text-white/80' : 'text-slate-600'
                    } hover:text-brand-primary`}
                  >
                    {item.label}
                    {item.children && <ChevronDown size={12} className={`ml-1 transition-transform ${activeMega === item.label ? 'rotate-180' : ''}`} />}
                    <span className={`absolute bottom-0 left-1/2 -translate-x-1/2 w-0 h-1 bg-brand-primary transition-all duration-500 ${
                      activeMega === item.label ? 'w-full' : ''
