                                        </Link>
                                    ))}
                                </div>
                            </div>
                        )}
                        {searchResults.industries.length > 0 && (
                            <div>
                                <h4 className="text-[10px] font-black uppercase tracking-[0.5em] text-brand-primary mb-6">Verticals</h4>
                                <div className="space-y-4">
                                    {searchResults.industries.map(i => (
