const express = require('express');
const path = require('path');
const nodemailer = require('nodemailer');
const { GoogleSpreadsheet } = require('google-spreadsheet');
const { JWT } = require('google-auth-library');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(express.json());
app.use(express.static(path.join(__dirname, 'dist')));

/**
 * GOOGLE SHEETS SETUP
 * Note: You must share your Google Sheet with the Service Account email.
 */
// We now pull this from the Environment Variables for security and flexibility
const SHEET_ID = process.env.SHEET_ID; 
const GOOGLE_SERVICE_ACCOUNT_EMAIL = process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
const GOOGLE_PRIVATE_KEY = process.env.GOOGLE_PRIVATE_KEY?.replace(/\\n/g, '\n');

/**
 * EMAIL SETUP
 * Recommended: Use an App Password if using Gmail.
 */
const transporter = nodemailer.createTransport({
  service: 'gmail',
  auth: {
    user: process.env.EMAIL_USER, // Your Gmail address
    pass: process.env.EMAIL_PASS, // Your Gmail App Password
  },
});

// Contact API Endpoint
app.post('/api/contact', async (req, res) => {
  const { firstName, lastName, email, service, message, timestamp } = req.body;

  if (!email || !firstName) {
    return res.status(400).json({ message: 'Missing required fields' });
  }

  try {
    // 1. Send Email Notification
    const mailOptions = {
      from: `"Onsective Web Leads" <${process.env.EMAIL_USER}>`,
      to: 'onsectivewebsite@gmail.com', // The specific receiver requested
      subject: `New Lead: ${firstName} ${lastName} - ${service}`,
      html: `
        <div style="font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px;">
          <h2 style="color: #C5A059;">New Project Inquiry</h2>
          <p><strong>Name:</strong> ${firstName} ${lastName}</p>
          <p><strong>Email:</strong> ${email}</p>
          <p><strong>Service:</strong> ${service}</p>
          <p><strong>Date:</strong> ${new Date(timestamp).toLocaleString()}</p>
          <hr />
          <p><strong>Message:</strong></p>
          <p style="background: #f9f9f9; padding: 15px; border-radius: 5px;">${message}</p>
        </div>
      `,
    };

    const emailPromise = transporter.sendMail(mailOptions);

    // 2. Append to Google Sheets
    let sheetPromise = Promise.resolve();

    // Only attempt sheet logic if credentials exist
    if (SHEET_ID && GOOGLE_SERVICE_ACCOUNT_EMAIL && GOOGLE_PRIVATE_KEY) {
      const auth = new JWT({
        email: GOOGLE_SERVICE_ACCOUNT_EMAIL,
        key: GOOGLE_PRIVATE_KEY,
        scopes: ['https://www.googleapis.com/auth/spreadsheets'],
      });

      const doc = new GoogleSpreadsheet(SHEET_ID, auth);

      sheetPromise = (async () => {
        await doc.loadInfo();
        const sheet = doc.sheetsByIndex[0];
        await sheet.addRow({
          Timestamp: new Date(timestamp).toLocaleString(),
          FirstName: firstName,
          LastName: lastName,
          Email: email,
          Service: service,
          Message: message
        });
      })();
    } else {
      console.warn('Google Sheets credentials missing in Env Vars. Skipping spreadsheet logging.');
    }

    // Wait for both operations
    await Promise.all([emailPromise, sheetPromise]);

    res.status(200).json({ message: 'Inquiry received successfully' });
  } catch (error) {
    console.error('API Error:', error);
    res.status(500).json({ message: 'Internal Server Error. Please try again later.' });
  }
});

// Health Check
app.get('/api/health', (req, res) => {
  res.json({ 
    status: 'healthy', 
    timestamp: new Date().toISOString(),
    service: 'Onsective Enterprise Backend'
  });
});

// Fallback to React app
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

